8	import { type WordTiming, parseWordTimings, wordSelector } from "../lib/types";
9	import { attachWordMenu } from "./word_menu";
10	
11	interface AudioPlayerDataset {
12	  audioUrl: string;
13	  timingsUrl: string;
14	  initialPosition?: string;
15	  bookTitle?: string;
16	  chapterTitle?: string;
17	  chapterId?: string;
18	  nextChapterId?: string;
19	  nextAudioUrl?: string;
20	  nextTimingsUrl?: string;
21	  nextChapterTitle?: string;
22	  prevChapterId?: string;
23	  prevAudioUrl?: string;
24	  prevTimingsUrl?: string;
25	  prevChapterTitle?: string;
26	}
27	
28	interface PlayerPrefs {
29	  readonly speed: number;
30	  readonly volume: number;
31	  readonly collapsed: boolean;
32	}
33	
34	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
35	  speed: 1,
36	  volume: 1,
37	  collapsed: false,
38	});
39	
40	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
41	
42	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
43	
44	const POSITION_REPORT_INTERVAL_MS = 5000;
45	const SKIP_SECONDS = 10;
46	const AUTO_SCROLL_GRACE_MS = 800;
47	
48	function coercePlayerPrefs(raw: unknown): Partial<PlayerPrefs> {
49	  if (!raw || typeof raw !== "object") return {};
50	  const r = raw as Record<string, unknown>;
51	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
52	  if (typeof r.speed === "number") out.speed = r.speed;
53	  if (typeof r.volume === "number") out.volume = r.volume;
54	  if (typeof r.collapsed === "boolean") out.collapsed = r.collapsed;
55	  return out;
56	}
57	
58	function migrateLegacyPlayerPrefs(): void {
59	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
60	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
61	  const legacyVolume = localStorage.getItem("readaloud-volume");
62	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
63	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
64	    return;
65	  const migrated: PlayerPrefs = {
66	    speed:
67	      legacySpeed !== null
68	        ? Number.parseFloat(legacySpeed)
69	        : PLAYER_PREFS_DEFAULTS.speed,
70	    volume:
71	      legacyVolume !== null
72	        ? Number.parseFloat(legacyVolume)
73	        : PLAYER_PREFS_DEFAULTS.volume,
74	    collapsed: legacyCollapsed === "true",
75	  };
76	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
77	}
78	
79	migrateLegacyPlayerPrefs();
80	const playerPrefs = new PersistedRecord<PlayerPrefs>(
81	  PLAYER_PREFS_KEY,
82	  PLAYER_PREFS_DEFAULTS,
83	  coercePlayerPrefs,
84	);
85	
86	function findActiveWord(
87	  timings: ReadonlyArray<WordTiming>,
88	  ms: number,
89	): number {
90	  let idx = -1;
91	  let lo = 0;
92	  let hi = timings.length - 1;
93	  while (lo <= hi) {
94	    const mid = (lo + hi) >>> 1;
95	    const t = timings[mid];
96	    if (!t) break;
97	    if (ms >= t.startMs && ms < t.endMs) {
98	      idx = mid;
99	      break;
100	    } else if (ms < t.startMs) {
101	      hi = mid - 1;
102	    } else {
103	      idx = mid;
104	      lo = mid + 1;
105	    }
106	  }
107	  if (idx >= 0 && idx < timings.length - 1) {
108	    const next = timings[idx + 1];
109	    if (next && ms >= next.startMs) idx += 1;
110	  }
111	  return idx;
112	}
113	
114	function formatTime(secs: number): string {
115	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
116	  const m = Math.floor(secs / 60);
117	  const s = Math.floor(secs % 60);
118	  return `${m}:${s < 10 ? "0" : ""}${s}`;
119	}
120	
121	// Monotonically increasing player-instance ID. Each hook mount gets one;
122	// shows up in every log line so we can tell apart pre-/post-remount
123	// instances when reading the browser console after the fact.
124	let nextPlayerId = 1;
125	
126	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
127	  (ctx) => {
128	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
129	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
130	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
131	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
132	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
133	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
134	
135	    if (!audio || !playPauseBtn) return;
136	
137	    const playerId = nextPlayerId++;
138	    // Detailed always-on logging for autoplay debugging. When the user
139	    // reports a symptom ("phone woke up at 11:07 and audio was at 0:00")
140	    // these lines + the chapter/book ids let us line up the JS-side state
141	    // machine with server logs (see reader_live.ex Logger.info calls).
142	    const log = (event: string, extra?: Record<string, unknown>): void => {
143	      const wall = new Date().toISOString();
144	      const t =
145	        typeof performance !== "undefined"
146	          ? Math.round(performance.now())
147	          : Date.now();
148	      const base: Record<string, unknown> = {
149	        player: playerId,
150	        chapter: ctx.dataset.chapterId,
151	        t,
152	      };
153	      if (extra) Object.assign(base, extra);
154	      console.log(`[autoplay ${wall}] ${event}`, base);
155	    };
156	
157	    let timings: ReadonlyArray<WordTiming> = [];
158	    let currentWordIndex = -1;
159	    let lastReportedMs = -1;
160	    let rafId: number | undefined;
161	    let wordMenuCleanup: (() => void) | undefined;
162	    let intersectionObserver: IntersectionObserver | undefined;
163	
164	    const applyAudioPrefs = (): void => {
165	      const p = playerPrefs.get();
166	      audio.playbackRate = p.speed;
167	      audio.volume = p.volume;
168	      updateSpeedBadge(p.speed);
169	    };
170	
171	    const updateTimeDisplay = (): void => {
172	      if (!timeDisplay) return;
173	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
174	    };
175	
176	    const updateSpeedBadge = (speed: number): void => {
177	      if (!speedBadge) return;
178	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
179	    };
180	
181	    const setSpeed = (speed: number): void => {
182	      playerPrefs.set({ speed });
183	      audio.playbackRate = speed;
184	      updateSpeedBadge(speed);
185	    };
186	
187	    const cycleSpeed = (direction: "up" | "down"): void => {
188	      const closest = SPEEDS.reduce((best, s) =>
189	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
190	          ? s
191	          : best,
192	      );
193	      setSpeed(cycleOption(SPEEDS, closest, direction));
194	    };
195	
196	    const togglePlayback = (): void => {
197	      if (audio.paused) audio.play();
198	      else audio.pause();
199	    };
200	
201	    const seekToWordIndex = (idx: number): void => {
202	      const t = timings[idx];
203	      if (!t) return;
204	      audio.currentTime = t.startMs / 1000;
205	      if (audio.paused) audio.play();
206	    };
207	
208	    // Word highlighting with auto-scroll
209	    const highlightWord = (ms: number): void => {
210	      if (!textContainer || timings.length === 0) return;
211	      const idx = findActiveWord(timings, ms);
212	      if (idx === currentWordIndex) return;
213	
214	      if (currentWordIndex >= 0) {
215	        const old = textContainer.querySelector<HTMLElement>(
216	          wordSelector(currentWordIndex),
217	        );
218	        old?.classList.remove("word-active");
219	        old?.classList.add("word-spoken");
220	      }

