          const ref = lv.handleEvent(event, handler as (p: unknown) => void);
          disposers.push(() => lv.removeHandleEvent(ref));
        },

        onDestroy(fn: () => void): void {
          disposers.push(fn);
        },

        onUpdate(fn: () => void): void {
          updateHandlers.push(fn);
        },
