  fontFamily: "serif",
  fontSize: 18,
  lineHeight: 1.8,
  maxWidth: 700,
  autoScroll: true,
  autoNextChapter: false,
});

const FONT_FAMILIES = ["serif", "sans", "mono"] as const;

function coerce(raw: unknown): Partial<ReaderSettings> {
